#!/usr/bin/env node
// Write results/pair_review.md: for every report and every shortened version, the exact lines removed.
// This is the file to hand-check before trusting a comparison.
"use strict";
const fs = require("fs");
const { T, CONDITIONS, rel, loadReports } = require("./lib.js");

const reports = loadReports();
const out = [
  "# Pair review: exactly what each shortened copy removes",
  "",
  "Generated by `node scripts/pair-review.js`. Lines starting with `-` are removed from the copy; `~` lines are edited in place (shown as before => after).",
  "A copy is used only if the checklist confirms that the target detail is gone and nothing else it measures changed.",
  "",
];
for (const c of CONDITIONS.slice(1)) {
  out.push("## " + T.CONDITIONS[c].label, "");
  for (const r of reports) {
    if (!T.applies(r, c)) continue;
    const kept = T.variant(r, c).split("\n");
    const pool = {};
    for (const x of kept) { const k = x.trim(); pool[k] = (pool[k] || 0) + 1; }
    const lines = [];
    for (const line of r.body.split("\n")) {
      const k = line.trim();
      if (!k) continue;
      if (pool[k]) { pool[k]--; continue; }
      const edited = kept.find((x) => x.trim() && k.startsWith(x.trim().slice(0, 25)) && x.trim() !== k);
      lines.push(edited ? "~ " + k.slice(0, 150) + "  =>  " + edited.trim().slice(0, 100) : "- " + k.slice(0, 150));
    }
    const pc = T.pairCheck(r, c);
    out.push("### " + r.id + " " + r.title + (pc.clean ? "" : "  (NOT CLEAN " + JSON.stringify(pc) + ")"), ...lines, "");
  }
}
fs.writeFileSync(rel("results", "pair_review.md"), out.join("\n"));
console.log("Wrote results/pair_review.md");
